const NOTION_TOKEN = 'NOTION_API_KEY';
const DB_ID = 'ae47436bd3d249e0b51fff48049a77a6';

const data = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.notion.com/v1/databases/${DB_ID}/query`,
  headers: {
    'Authorization': `Bearer ${NOTION_TOKEN}`,
    'Notion-Version': '2022-06-28',
    'Content-Type': 'application/json'
  },
  body: {
    filter: {
      property: 'Durum',
      status: { equals: '🟢 Üretime Hazır' }
    },
    page_size: 20
  },
  json: true
});

return (data.results || []).map(p => ({
  json: {
    page_id: p.id,
    olay: p.properties['Olay']?.title?.[0]?.plain_text || '',
    source_id: p.properties['Source_ID']?.rich_text?.[0]?.plain_text || '',
    url: p.properties['Trend URL']?.url || ''
  }
}));

const NOTION_TOKEN = 'NOTION_API_KEY';

for (const item of items) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `https://api.notion.com/v1/pages/${item.json.page_id}`,
    headers: {
      'Authorization': `Bearer ${NOTION_TOKEN}`,
      'Notion-Version': '2022-06-28',
      'Content-Type': 'application/json'
    },
    body: {
      properties: {
        'Durum': { status: { name: '✅ Paylaşıldı' } }
      }
    },
    json: true
  });
  // Rate limit
  await new Promise(r => setTimeout(r, 1000));
}
return items;
